import {
  IconChevronLeft,
  IconChevronRight,
  IconChevronsLeft,
  IconChevronsRight,
  IconDots,
} from '@tabler/icons-react';
import { cva } from 'class-variance-authority';
import {
  type ComponentProps,
  type ComponentRef,
  type KeyboardEvent,
  type FocusEvent,
  type ChangeEvent,
  createContext,
  forwardRef,
  useContext,
  useState,
} from 'react';

import { cn } from '../../../../lib/utils';
import { Button } from '../button';
import { Input } from '../input';
import { SelectTrigger } from '../select';

type PaginationSize = 'default' | 'small';

const PaginationSizeContext = createContext<PaginationSize>('default');

const usePaginationSize = () => useContext(PaginationSizeContext);

const paginationLinkVariants = cva(
  'text-base font-medium leading-5 tracking-tightest',
  {
    variants: {
      size: {
        default: '',
        small: 'text-sm leading-4.5 tracking-tight',
      },
      active: {
        true: 'bg-toggled text-toggled-foreground hover:bg-toggled-hover hover:text-toggled-foreground',
        false: '',
      },
    },
    defaultVariants: {
      size: 'default',
      active: false,
    },
  }
);

const paginationEllipsisVariants = cva('flex items-center justify-center', {
  variants: {
    size: {
      default: 'h-9 w-9',
      small: 'h-7 w-7',
    },
  },
  defaultVariants: {
    size: 'default',
  },
});

const paginationStatusVariants = cva('px-4 text-sm text-muted-foreground', {
  variants: {
    size: {
      default: '',
      small: 'px-3',
    },
  },
  defaultVariants: {
    size: 'default',
  },
});

const getPaginationButtonStyles = (size: PaginationSize = 'default') => {
  const buttonSize = size === 'small' ? 'icon-sm' : 'icon';
  const radiusClass = size === 'small' ? 'rounded' : 'rounded-md';

  return { buttonSize, radiusClass } as const;
};

const Pagination = forwardRef<ComponentRef<'nav'>, ComponentProps<'nav'>>(
  ({ className, ...props }, ref) => {
    return (
      <nav
        ref={ref}
        aria-label="pagination"
        data-slot="pagination"
        className={cn('mx-auto flex w-full justify-center', className)}
        {...props}
      />
    );
  }
);
Pagination.displayName = 'Pagination';

const PaginationContent = forwardRef<
  ComponentRef<'ul'>,
  ComponentProps<'ul'> & { size?: PaginationSize }
>(({ className, size = 'default', ...props }, ref) => {
  return (
    <PaginationSizeContext.Provider value={size}>
      <ul
        ref={ref}
        data-slot="pagination-content"
        data-size={size}
        className={cn('flex flex-row items-center gap-1', className)}
        {...props}
      />
    </PaginationSizeContext.Provider>
  );
});
PaginationContent.displayName = 'PaginationContent';

const PaginationItem = forwardRef<ComponentRef<'li'>, ComponentProps<'li'>>(
  ({ className, ...props }, ref) => {
    return (
      <li
        ref={ref}
        data-slot="pagination-item"
        className={cn(className)}
        {...props}
      />
    );
  }
);
PaginationItem.displayName = 'PaginationItem';

const PaginationStatus = forwardRef<
  ComponentRef<'output'>,
  ComponentProps<'output'> & { size?: PaginationSize }
>(({ className, size, ...props }, ref) => {
  const inheritedSize = usePaginationSize();
  const resolvedSize = size ?? inheritedSize;

  return (
    <output
      ref={ref}
      data-slot="pagination-status"
      className={cn(
        paginationStatusVariants({ size: resolvedSize }),
        className
      )}
      {...props}
    />
  );
});
PaginationStatus.displayName = 'PaginationStatus';

const PaginationSelectTrigger = forwardRef<
  ComponentRef<typeof SelectTrigger>,
  ComponentProps<typeof SelectTrigger>
>(({ className, size, ...props }, ref) => {
  const inheritedSize = usePaginationSize();
  const isPaginationSmall = inheritedSize === 'small' && size === undefined;
  const resolvedSize = size ?? (isPaginationSmall ? 'sm' : 'default');

  return (
    <SelectTrigger
      ref={ref}
      size={resolvedSize}
      data-slot="pagination-select-trigger"
      className={cn(
        'min-h-0 min-w-0 gap-1 text-sm leading-4.5 font-medium py-1.75',
        'data-[size=sm]:h-7 data-[size=default]:h-9',
        isPaginationSmall ? 'w-16 px-2 rounded' : 'w-18 pl-3 pr-2',
        className
      )}
      {...props}
    />
  );
});
PaginationSelectTrigger.displayName = 'PaginationSelectTrigger';

type PaginationLinkProps = {
  isActive?: boolean;
  isDisabled?: boolean;
  size?: PaginationSize;
} & ComponentProps<'a'>;

const PaginationLink = forwardRef<ComponentRef<'a'>, PaginationLinkProps>(
  ({ className, isActive, isDisabled, size, ...props }, ref) => {
    const inheritedSize = usePaginationSize();
    const resolvedSize = size ?? inheritedSize;
    const { buttonSize, radiusClass } = getPaginationButtonStyles(resolvedSize);

    return (
      <Button
        variant="ghost"
        size={buttonSize}
        data-slot="pagination-link"
        data-active={isActive}
        className={cn(
          radiusClass,
          paginationLinkVariants({ size: resolvedSize, active: isActive }),
          isDisabled && 'pointer-events-none opacity-50',
          className
        )}
        render={
          <a
            ref={ref}
            aria-current={isActive ? 'page' : undefined}
            aria-disabled={isDisabled || undefined}
            tabIndex={isDisabled ? -1 : undefined}
            {...props}
          />
        }
      />
    );
  }
);
PaginationLink.displayName = 'PaginationLink';

const PaginationFirst = forwardRef<
  ComponentRef<'a'>,
  Omit<PaginationLinkProps, 'isActive'>
>(({ className, size, ...props }, ref) => {
  const inheritedSize = usePaginationSize();
  const resolvedSize = size ?? inheritedSize;
  const { buttonSize, radiusClass } = getPaginationButtonStyles(resolvedSize);
  const { isDisabled, ...linkProps } = props;

  return (
    <Button
      variant="ghost"
      size={buttonSize}
      data-slot="pagination-first"
      className={cn(
        radiusClass,
        isDisabled && 'pointer-events-none opacity-50',
        className
      )}
      render={
        <a
          ref={ref}
          aria-label="Go to first page"
          aria-disabled={isDisabled || undefined}
          tabIndex={isDisabled ? -1 : undefined}
          {...linkProps}
        >
          <IconChevronsLeft />
        </a>
      }
    />
  );
});
PaginationFirst.displayName = 'PaginationFirst';

const PaginationPrevious = forwardRef<
  ComponentRef<'a'>,
  Omit<PaginationLinkProps, 'isActive'>
>(({ className, size, ...props }, ref) => {
  const inheritedSize = usePaginationSize();
  const resolvedSize = size ?? inheritedSize;
  const { buttonSize, radiusClass } = getPaginationButtonStyles(resolvedSize);
  const { isDisabled, ...linkProps } = props;

  return (
    <Button
      variant="ghost"
      size={buttonSize}
      data-slot="pagination-previous"
      className={cn(
        radiusClass,
        isDisabled && 'pointer-events-none opacity-50',
        className
      )}
      render={
        <a
          ref={ref}
          aria-label="Go to previous page"
          aria-disabled={isDisabled || undefined}
          tabIndex={isDisabled ? -1 : undefined}
          {...linkProps}
        >
          <IconChevronLeft />
        </a>
      }
    />
  );
});
PaginationPrevious.displayName = 'PaginationPrevious';

const PaginationNext = forwardRef<
  ComponentRef<'a'>,
  Omit<PaginationLinkProps, 'isActive'>
>(({ className, size, ...props }, ref) => {
  const inheritedSize = usePaginationSize();
  const resolvedSize = size ?? inheritedSize;
  const { buttonSize, radiusClass } = getPaginationButtonStyles(resolvedSize);
  const { isDisabled, ...linkProps } = props;

  return (
    <Button
      variant="ghost"
      size={buttonSize}
      data-slot="pagination-next"
      className={cn(
        radiusClass,
        isDisabled && 'pointer-events-none opacity-50',
        className
      )}
      render={
        <a
          ref={ref}
          aria-label="Go to next page"
          aria-disabled={isDisabled || undefined}
          tabIndex={isDisabled ? -1 : undefined}
          {...linkProps}
        >
          <IconChevronRight />
        </a>
      }
    />
  );
});
PaginationNext.displayName = 'PaginationNext';

const PaginationLast = forwardRef<
  ComponentRef<'a'>,
  Omit<PaginationLinkProps, 'isActive'>
>(({ className, size, ...props }, ref) => {
  const inheritedSize = usePaginationSize();
  const resolvedSize = size ?? inheritedSize;
  const { buttonSize, radiusClass } = getPaginationButtonStyles(resolvedSize);
  const { isDisabled, ...linkProps } = props;

  return (
    <Button
      variant="ghost"
      size={buttonSize}
      data-slot="pagination-last"
      className={cn(
        radiusClass,
        isDisabled && 'pointer-events-none opacity-50',
        className
      )}
      render={
        <a
          ref={ref}
          aria-label="Go to last page"
          aria-disabled={isDisabled || undefined}
          tabIndex={isDisabled ? -1 : undefined}
          {...linkProps}
        >
          <IconChevronsRight />
        </a>
      }
    />
  );
});
PaginationLast.displayName = 'PaginationLast';

const PaginationEllipsis = forwardRef<
  ComponentRef<'span'>,
  ComponentProps<'span'> & { size?: PaginationSize }
>(({ className, size, ...props }, ref) => {
  const inheritedSize = usePaginationSize();
  const resolvedSize = size ?? inheritedSize;

  return (
    <span
      ref={ref}
      aria-hidden
      data-slot="pagination-ellipsis"
      className={cn(
        paginationEllipsisVariants({ size: resolvedSize }),
        className
      )}
      {...props}
    >
      <IconDots className="h-4 w-4" />
      <span className="sr-only">More pages</span>
    </span>
  );
});
PaginationEllipsis.displayName = 'PaginationEllipsis';

type PaginationTeleportProps = {
  currentPage: number;
  totalPages: number;
  onPageChange: (page: number) => void;
  size?: PaginationSize;
} & Omit<
  ComponentProps<typeof Input>,
  'size' | 'value' | 'onChange' | 'children' | 'type'
>;

const PaginationTeleport = forwardRef<
  ComponentRef<typeof Input>,
  PaginationTeleportProps
>(
  (
    { className, currentPage, totalPages, onPageChange, size, ...props },
    ref
  ) => {
    const inheritedSize = usePaginationSize();
    const resolvedSize = size ?? inheritedSize;
    const [editingValue, setEditingValue] = useState('');
    const [isEditing, setIsEditing] = useState(false);

    const isSmall = resolvedSize === 'small';

    const inputClassName = cn(
      'font-medium tabular-nums text-center w-20',
      isSmall ? 'h-7 text-sm px-2' : 'px-2',
      className
    );

    const displayValue = isEditing
      ? editingValue
      : `${currentPage}/${totalPages}`;

    const handleFocus = (e: FocusEvent<HTMLInputElement>) => {
      setIsEditing(true);
      setEditingValue(currentPage.toString());
      setTimeout(() => e.target.select(), 0);
    };

    const handleBlur = () => {
      setIsEditing(false);
      const pageNum = Number.parseInt(editingValue, 10);

      if (!Number.isNaN(pageNum) && pageNum >= 1 && pageNum <= totalPages) {
        onPageChange(pageNum);
      }
      setEditingValue('');
    };

    const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
      const value = e.target.value;

      if (value === '' || /^\d+$/.test(value)) {
        setEditingValue(value);
      }
    };

    const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
      if (e.key === 'Enter') {
        e.currentTarget.blur();
      } else if (e.key === 'Escape') {
        setEditingValue(currentPage.toString());
        e.currentTarget.blur();
      }
    };

    return (
      <Input
        ref={ref}
        type="text"
        inputMode="numeric"
        value={displayValue}
        onChange={handleChange}
        onFocus={handleFocus}
        onBlur={handleBlur}
        onKeyDown={handleKeyDown}
        data-slot="pagination-teleport"
        className={inputClassName}
        aria-label={`Current page, page ${currentPage} of ${totalPages}`}
        {...props}
      />
    );
  }
);
PaginationTeleport.displayName = 'PaginationTeleport';

const PaginationResultsPerPage = forwardRef<
  ComponentRef<'li'>,
  ComponentProps<'li'>
>(({ className, ...props }, ref) => {
  return (
    <li
      ref={ref}
      data-slot="pagination-results-per-page"
      className={cn('flex items-center gap-2 pl-4', className)}
      {...props}
    />
  );
});
PaginationResultsPerPage.displayName = 'PaginationResultsPerPage';

const PaginationResultsPerPageLabel = forwardRef<
  ComponentRef<'span'>,
  ComponentProps<'span'>
>(({ className, ...props }, ref) => {
  return (
    <span
      ref={ref}
      data-slot="pagination-results-per-page-label"
      className={cn('text-sm text-muted-foreground', className)}
      {...props}
    />
  );
});
PaginationResultsPerPageLabel.displayName = 'PaginationResultsPerPageLabel';

export {
  Pagination,
  PaginationContent,
  PaginationEllipsis,
  PaginationFirst,
  PaginationItem,
  PaginationLast,
  PaginationLink,
  PaginationNext,
  PaginationPrevious,
  PaginationResultsPerPage,
  PaginationResultsPerPageLabel,
  PaginationSelectTrigger,
  PaginationStatus,
  PaginationTeleport,
  paginationEllipsisVariants,
  paginationLinkVariants,
  paginationStatusVariants,
};

@import url("https://fonts.googleapis.com/css2?family=Inter:wght@100..900&family=Space+Grotesk:wght@300..700&family=Source+Code+Pro:wght@200..900&display=swap");
@import "tailwindcss";
@import "tw-animate-css";
@import "./colors.css";

@custom-variant dark (&:is(.dark *));

/* Dark mode configuration */
@variant dark (@media (prefers-color-scheme: dark));
@variant dark (.dark &);

@theme inline {
  /* Container query breakpoint overrides for layout system */
  --container-2xl: 40rem; /* 640px - Override Tailwind's default 672px */
  --container-8xl: 96rem; /* 1536px - Custom breakpoint for widest layouts */

  /* Typography scale overrides - font sizes */
  --text-2xs: 0.625rem;
  --text-2xl: 1.5rem;
  --text-3xl: 1.75rem;
  --text-4xl: 2rem;
  --text-5xl: 2.25rem;

  /* Typography scale overrides - line heights */
  --text-2xs--line-height: 0.75rem;
  --text-xs--line-height: 0.875rem;
  --text-sm--line-height: 1.125rem;
  --text-base--line-height: 1.25rem;
  --text-lg--line-height: 1.5rem;
  --text-xl--line-height: 1.5rem;
  --text-2xl--line-height: 1.75rem;
  --text-3xl--line-height: 2rem;
  --text-4xl--line-height: 2.5rem;
  --text-5xl--line-height: 2.75rem;

  --font-sans: var(--font-inter);
  --font-marketing: var(--font-space-grotesk);
  --font-mono: var(--font-source-code-pro);
  --tracking-tight: -0.04px;
  --tracking-tighter: -0.08px;
  --tracking-tightest: -0.1px;
  --shadow-sm: 0 1px 2px 0 var(--effect-shadow-sm);
  --shadow-default:
    0 1px 3px 0 var(--effect-shadow-md), 0 1px 2px 0 var(--effect-shadow-sm);
  --shadow-md:
    0 4px 6px -1px var(--effect-shadow-md),
    0 2px 4px -1px var(--effect-shadow-sm);
  --shadow-lg:
    0 10px 15px -3px var(--effect-shadow-lg),
    0 4px 6px -2px var(--effect-shadow-sm);
  --shadow-xl:
    0 20px 25px -5px var(--effect-shadow-xl),
    0 10px 10px -5px var(--effect-shadow-lg);
  --shadow-focus-ring: 0 0 0 2px var(--ring), 0 0 0 4px var(--ring-muted);
  --shadow-focus-ring-destructive:
    0 0 0 2px var(--ring-critical), 0 0 0 4px var(--ring-critical-shadow);

  --radius-none: 0px;
  --radius-xs: 2px;
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 8px;
  --radius-xl: 12px;
  --radius-2xl: 16px;
  --radius-3xl: 24px;
  --radius-4xl: 32px;
  --radius-full: 9999px;
  --avatar-icon-default: 1.09375rem;
  --avatar-icon-xs: 0.875rem;
  --avatar-icon-xxs: 0.65625rem;
  --avatar-image-backdrop: rgba(2, 6, 23, 0.2);

  /* Legacy semantic utility aliases */
  --color-primary: var(--primary);
  --color-primary-hover: var(--primary-hover);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-hover: var(--secondary-hover);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-ring-shadow: var(--ring-shadow);
  --color-ring-destructive: var(--ring-destructive);
  --color-ring-destructive-shadow: var(--ring-destructive-shadow);
  --color-destructive: var(--destructive);
  --color-destructive-hover: var(--destructive-hover);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-warning: var(--warning);
  --color-warning-hover: var(--warning-hover);
  --color-warning-foreground: var(--warning-foreground);
  --color-success: var(--success);
  --color-success-hover: var(--success-hover);
  --color-success-foreground: var(--success-foreground);
  --color-neutral: var(--neutral);
  --color-neutral-hover: var(--neutral-hover);
  --color-neutral-foreground: var(--neutral-foreground);
  --color-undefined: var(--undefined);
  --color-undefined-hover: var(--undefined-hover);
  --color-undefined-foreground: var(--undefined-foreground);
  --color-disabled: var(--disabled);
  --color-disabled-foreground: var(--disabled-foreground);
  --color-hover: var(--hover);
  --color-foreground-link: var(--foreground-link);
  --color-backdrop: var(--backdrop);
  --color-toggled: var(--toggled);
